// Clean-room bounded iterative-compression feedback vertex set profile.
const N:usize=8;const INPUT:usize=59;const FAILURE:u64=0xffffffffffffffff;
fn bitCount(x0:u64)usize{var x=x0;var n:usize=0;while(x!=0):(x>>=1)n+=@intCast(x&1);return n;}
fn root(parent:*[N]usize,x0:usize)usize{var x=x0;while(parent[x]!=x){parent[x]=parent[parent[x]];x=parent[x];}return x;}
fn forest(g:*const[N][N]bool,n:usize,vertices:u64)bool{var parent:[N]usize=undefined;for(0..n)|i|parent[i]=i;for(0..n)|u|{if((vertices>>@intCast(u))&1!=0){var v=u+1;while(v<n):(v+=1){if((vertices>>@intCast(v))&1!=0&&g[u][v]){const a=root(&parent,u);const b=root(&parent,v);if(a==b)return false;parent[a]=b;}}}}return true;}
fn compress(g:*const[N][N]bool,n:usize,prefix:u64,k:usize,current:u64)u64{var x=current;while(true){const cx=bitCount(x);const excluded=current&~x;if(cx<=k&&forest(g,n,excluded)){const eligible=prefix&~current;var s=eligible;while(true){if(bitCount(s)<=k-cx&&forest(g,n,prefix&~(x|s)))return x|s;if(s==0)break;s=(s-1)&eligible;}}if(x==0)break;x=(x-1)&current;}return FAILURE;}
fn solveBudget(g:*const[N][N]bool,n:usize,k:usize)u64{var fvs:u64=0;for(0..n)|i|{const prefix=(@as(u64,1)<<@intCast(i+1))-1;const candidate=fvs|(@as(u64,1)<<@intCast(i));if(bitCount(candidate)<=k){fvs=candidate;continue;}fvs=compress(g,n,prefix,k,candidate);if(fvs==FAILURE)return FAILURE;}return fvs;}
fn minimumFvs(g:*const[N][N]bool,n:usize,limit:usize)i64{for(0..limit+1)|k|{if(solveBudget(g,n,k)!=FAILURE)return @intCast(k);}return -1;}
fn put(out:[*]u8,at:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|i|out[at+i]=@truncate(bits>>@intCast(8*i));}
export fn undirected_feedback_vertex_set(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{if(input_opt==null||length<3||length>INPUT)return -1;const input=input_opt.?;const n64=input[0];const m64=input[1];const limit=input[2];if(n64<1||n64>8||m64<0||m64>28||limit<0||limit>4||length!=3+2*@as(usize,@intCast(m64)))return -1;const n:usize=@intCast(n64);const m:usize=@intCast(m64);var g:[N][N]bool=@splat(@splat(false));var pu:i64=-1;var pv:i64=-1;for(0..m)|e|{const u=input[3+2*e];const v=input[4+2*e];if(u<0||v<=u||v>=n64||u<pu||(u==pu&&v<=pv))return -1;g[@intCast(u)][@intCast(v)]=true;g[@intCast(v)][@intCast(u)]=true;pu=u;pv=v;}if(output_opt==null||capacity<16)return -2;const minimum=minimumFvs(&g,n,@intCast(limit));const out=output_opt.?;put(out,0,if(minimum<0)0 else 1);put(out,8,minimum);return 16;}
